CREATE TABLE system_cache_operations(owner_id text NOT NULL REFERENCES users(id),request_id uuid NOT NULL,fingerprint text NOT NULL,instance_id uuid NOT NULL,process_id uuid NOT NULL,revision bigint NOT NULL,state text NOT NULL CHECK(state IN('admitted','completed','unknown','rejected')),result jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),finished_at timestamptz,PRIMARY KEY(owner_id,request_id));
CREATE FUNCTION retain_system_cache_operation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.state<>'admitted' OR NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.request_id IS DISTINCT FROM OLD.request_id OR NEW.fingerprint IS DISTINCT FROM OLD.fingerprint OR NEW.instance_id IS DISTINCT FROM OLD.instance_id OR NEW.process_id IS DISTINCT FROM OLD.process_id OR NEW.revision IS DISTINCT FROM OLD.revision OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'cache operation retained' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER retain_system_cache_operation BEFORE UPDATE OR DELETE ON system_cache_operations FOR EACH ROW EXECUTE FUNCTION retain_system_cache_operation();
